type OrderMsg = { kind: 'order'; order: Order };
type InvoiceMsg = { kind: 'invoice'; invoice: Invoice };

export class Channel<T> {
  constructor(readonly topic: string) {}
  publish(msg: T): void { broker.send(this.topic, msg); }
}
export const orderChannel = new Channel<OrderMsg>('orders');   // generic = the binding
